+    <div id="attempts-section"><div class="loading-msg">Loading…</div></div>
+
+    <!-- files modified -->
+    <div class="section-title">Files Modified</div>
+    <div class="tbl-wrap">
+      <table>
+        <thead>
+          <tr><th>File</th><th>BC IDs Applied</th></tr>
+        </thead>
+        <tbody id="files-tbody"><tr><td colspan="2" class="loading-msg">Loading…</td></tr></tbody>
+      </table>
+    </div>
+
+  </div>
+
+  <!-- ══════════════════════════════════════════════ BREAKING CHANGES ══ -->
+  <div id="tab-breaking" class="tab-panel">
+    <div class="section-title">Breaking Changes Extracted from Migration Guide</div>
+    <div id="bc-list"><div class="loading-msg">Loading…</div></div>
+  </div>
+
+  <!-- ══════════════════════════════════════════════ USAGE MAP ══ -->
+  <div id="tab-usage" class="tab-panel">
+    <div class="section-title">Usage Sites Found by Scanner</div>
+
+    <div style="margin-bottom:20px;">
+      <div class="section-title" style="margin-top:0;">Sites per Breaking Change</div>
+      <div class="bar-chart" id="usage-bar-chart"><div class="loading-msg">Loading…</div></div>
+    </div>
+
+    <div class="section-title">Detailed Sites</div>
+    <div id="usage-detail"><div class="loading-msg">Loading…</div></div>
+  </div>
+
+  <!-- ══════════════════════════════════════════════ TEST RUNNER ══ -->
+  <div id="tab-tests" class="tab-panel">
+    <div class="section-title">Live Test Runner</div>
+    <p style="color:var(--muted);font-size:13px;margin-bottom:16px;">
+      Runs <code>python -m pytest --tb=no -q</code> against the current repo state.
+    </p>
+    <button class="run-btn" id="run-btn" onclick="runTests()">▶ Run pytest now</button>
+    <div class="test-result-box" id="test-result-box">
+      <div class="big-status" id="test-status"></div>
+      <div class="summary-text" id="test-summary"></div>
+    </div>
+  </div>
+
+  <!-- ══════════════════════════════════════════════ FULL REPORT ══ -->
+  <div id="tab-report" class="tab-panel">
+    <div class="section-title">UPGRADE_REPORT.md</div>
+    <div class="md-box" id="md-box"><div class="loading-msg">Loading…</div></div>
+  </div>
+
+</main>
+
+<script>
+// ── tab switching ──────────────────────────────────────────────────────────
+function switchTab(name, btn) {
+  document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
+  document.querySelectorAll('nav button').forEach(b => b.classList.remove('active'));
+  document.getElementById('tab-' + name).classList.add('active');
+  btn.classList.add('active');
+}
+
+// ── fetch helpers ──────────────────────────────────────────────────────────
+const api = path => fetch(path).then(r => { if (!r.ok) throw new Error(r.status); return r.json(); });
+
+// ── BC id → colour class ───────────────────────────────────────────────────
+const bcColour = id => {
+  const map = { 'BC-001':'#f59e0b','BC-002':'#6366f1','BC-003':'#22c55e','BC-004':'#3b82f6','BC-005':'#8b5cf6','BC-006':'#ef4444' };
+  return map[id] || '#7c84a6';
+};
+
+// ── Overview ───────────────────────────────────────────────────────────────
+function buildOverview(report) {
+  // stat cards
+  const totalSites = 15;
+  const statusColor = report.final_status === 'green' ? 'green' : 'red';
+  const statusText  = report.final_status === 'green' ? '✅ GREEN' : '❌ FAILED';
+  document.getElementById('stat-grid').innerHTML = `
+    <div class="stat-card"><div class="label">Final Status</div><div class="value ${statusColor}">${statusText}</div><div class="sub">77 / 77 tests</div></div>
+    <div class="stat-card"><div class="label">Breaking Changes</div><div class="value blue">6</div><div class="sub">BC-001 – BC-006</div></div>
+    <div class="stat-card"><div class="label">Usage Sites</div><div class="value purple">${totalSites}</div><div class="sub">across src/ + tests/</div></div>
+    <div class="stat-card"><div class="label">Files Patched</div><div class="value yellow">${report.files_modified.length}</div><div class="sub">by 2 migrators</div></div>
+    <div class="stat-card"><div class="label">Verifier Attempts</div><div class="value">${report.test_runs.length}</div><div class="sub">attempt 2 green</div></div>
+    <div class="stat-card"><div class="label">Human-Review Flags</div><div class="value yellow">${report.needs_human_review.length}</div><div class="sub">BC-006 auto-fixed</div></div>
+  `;
+
+  // header badge
+  document.getElementById('header-badge').textContent =
+    report.final_status === 'green' ? '77/77 GREEN' : 'FAILED';
+
+  // attempts
+  const attemptsHtml = report.test_runs.map((r, i) => `
+    <div class="attempt-row">
+      <div class="attempt-dot ${r.passed ? 'pass' : 'fail'}"></div>
+      <div class="attempt-label">
+        <strong>Attempt ${r.attempt}</strong> —
+        ${r.passed
+          ? '<span class="chip-green">PASSED</span> 77 / 77'
+          : `<span class="chip-red">FAILED</span> ${r.failure_count} failure${r.failure_count !== 1 ? 's' : ''}`}
+        ${!r.passed ? ' · BC-006 <code>TypeError → ValidationError</code> auto-fixed' : ''}
+      </div>
+    </div>
+  `).join('');
+  document.getElementById('attempts-section').innerHTML = attemptsHtml;
+
+  // files modified — figure out BC IDs per file from changes array
+  const fileBCs = {};
+  for (const c of report.changes) {
+    if (!fileBCs[c.file]) fileBCs[c.file] = new Set();
+    fileBCs[c.file].add(c.bc_id);
+  }
+  for (const h of report.needs_human_review) {
+    if (!fileBCs[h.file]) fileBCs[h.file] = new Set();
+    fileBCs[h.file].add(h.bc_id);
+  }
+  const filesHtml = report.files_modified.map(f => {
+    const bcs = fileBCs[f] ? [...fileBCs[f]].sort() : [];
+    const badges = bcs.map(id => `<span class="badge-bc" style="background:rgba(99,102,241,0.15);color:#a5b4fc;">${id}</span>`).join('');
+    return `<tr><td><code>${f}</code></td><td>${badges || '<span style="color:var(--muted)">—</span>'}</td></tr>`;
+  }).join('');
+  document.getElementById('files-tbody').innerHTML = filesHtml;
+}
+
+// ── Breaking Changes ───────────────────────────────────────────────────────
+function buildBreaking(bcs) {
+  const html = bcs.map(bc => `
+    <div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:18px 22px;margin-bottom:14px;border-left:4px solid ${bcColour(bc.id)};">
+      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
+        <span class="badge-bc" style="font-size:12px;padding:3px 9px;">${bc.id}</span>
+        <strong style="font-size:14px;">${bc.title}</strong>
+        <span style="margin-left:auto;font-size:11px;color:var(--muted);">confidence ≥ ${Math.round(bc.confidence_required * 100)}%</span>
+      </div>
+      <p style="color:var(--muted);font-size:13px;margin-bottom:10px;">${bc.description}</p>
+      <div style="display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap;">
+        <div style="flex:1;min-width:220px;">
+          <div style="font-size:10px;color:var(--red);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:3px;">v1 (old)</div>
+          <code style="display:block;padding:6px 10px;background:rgba(239,68,68,0.08);border-color:rgba(239,68,68,0.25);color:#fca5a5;">${escHtml(bc.old_pattern)}</code>
+        </div>
+        <div style="padding-top:20px;color:var(--muted);font-size:16px;">→</div>
+        <div style="flex:1;min-width:220px;">
+          <div style="font-size:10px;color:var(--green);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:3px;">v2 (new)</div>
+          <code style="display:block;padding:6px 10px;background:rgba(34,197,94,0.08);border-color:rgba(34,197,94,0.25);color:#86efac;">${escHtml(bc.new_pattern)}</code>
+        </div>
+      </div>
+      <div style="margin-top:8px;font-size:11px;color:var(--muted);">Detection hint: <code>${escHtml(bc.detection_hint)}</code></div>
+    </div>
+  `).join('');
+  document.getElementById('bc-list').innerHTML = html;
+}
+
+// ── Usage Map ─────────────────────────────────────────────────────────────
+function buildUsage(usageMap) {
+  // bar chart
+  const barHtml = Object.entries(usageMap).map(([id, sites]) => {
+    const max = 6;
+    const pct = Math.round((sites.length / max) * 100);
+    return `
+      <div class="bar-row">
+        <div class="bar-label"><span class="badge-bc">${id}</span></div>
+        <div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${bcColour(id)};"></div></div>
+        <div class="bar-count">${sites.length}</div>
+      </div>
+    `;
+  }).join('');
+  document.getElementById('usage-bar-chart').innerHTML = barHtml;
+
+  // detail — group by file
+  const byFile = {};
+  for (const [id, sites] of Object.entries(usageMap)) {
+    for (const site of sites) {
+      if (!byFile[site.file]) byFile[site.file] = [];
+      byFile[site.file].push({ ...site, bc_id: id });
+    }
+  }
+  for (const arr of Object.values(byFile)) arr.sort((a, b) => a.line - b.line);
+
+  const detailHtml = Object.entries(byFile).map(([file, sites]) => `
+    <div class="usage-file-group">
+      <div class="usage-file-name">📄 <code style="background:transparent;border:none;color:var(--blue);">${file}</code></div>
+      ${sites.map(s => `
+        <div class="usage-site">
+          <span class="line-num">L${s.line}</span>
+          <span class="badge-bc" style="flex-shrink:0;">${s.bc_id}</span>
+          <code>${escHtml(s.snippet.trim())}</code>
+        </div>
+      `).join('')}
+    </div>
+  `).join('');
+  document.getElementById('usage-detail').innerHTML = detailHtml;
+}
+
+// ── Full report ────────────────────────────────────────────────────────────
+function buildReport(data) {
+  document.getElementById('md-box').textContent = data.markdown;
+}
+
+// ── Test runner ────────────────────────────────────────────────────────────
+function runTests() {
+  const btn = document.getElementById('run-btn');
+  const box = document.getElementById('test-result-box');
+  btn.disabled = true;
+  btn.innerHTML = '<span class="spinner"></span> Running…';
+  box.classList.remove('visible');
+
+  api('/api/run-tests').then(result => {
+    document.getElementById('test-status').innerHTML = result.passed
+      ? '<span class="green">✅ PASSED</span>'
+      : '<span class="red">❌ FAILED</span>';
+    document.getElementById('test-summary').textContent = result.summary;
+    box.classList.add('visible');
+  }).catch(err => {
+    document.getElementById('test-status').innerHTML = '<span class="red">Error</span>';
+    document.getElementById('test-summary').textContent = String(err);
+    box.classList.add('visible');
+  }).finally(() => {
+    btn.disabled = false;
+    btn.innerHTML = '▶ Run pytest now';
+  });
+}
+
+// ── util ───────────────────────────────────────────────────────────────────
+function escHtml(s) {
+  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
+}
+
+// ── bootstrap — load all data in parallel ─────────────────────────────────
+Promise.all([
+  api('/api/upgrade-report'),
+  api('/api/breaking-changes'),
+  api('/api/usage-map'),
+  api('/api/upgrade-report-md'),
+]).then(([report, bcs, usageMap, md]) => {
+  buildOverview(report);
+  buildBreaking(bcs);
+  buildUsage(usageMap);
+  buildReport(md);
+}).catch(err => {
+  document.body.innerHTML = `<div style="padding:40px;color:#ef4444;font-family:monospace;">
+    Failed to load data from backend.<br><br>
+    Make sure the server is running:<br>
+    <code>python dashboard/server.py</code><br><br>
+    Error: ${err}
+  </div>`;
+});
+</script>
+</body>
+</html>
